exercise.solution:
fn letter(score: u32) -> char {
    if score >= 90 {
        'A'
    } else if score >= 80 {
        'B'
    } else if score >= 70 {
        'C'
    } else if score >= 60 {
        'D'
    } else {
        'F'
    }
}

fn average_and_best(scores: [u32; 4]) -> (f64, u32) {
    let mut sum = 0;
    let mut best = 0;
    for score in scores {
        sum += score;
        if score > best {
            best = score;
        }
    }
    (sum as f64 / 4.0, best)
}

fn rounds_to_pass(score: u32, bonus: u32) -> u32 {
    let mut current = score;
    let mut rounds = 0;
    loop {
        if current >= 60 {
            break rounds;
        }
        current += bonus;
        rounds += 1;
    }
}

fn main() {
    for score in [100, 90, 89, 60, 59, 0] {
        println!("{score} -> {}", letter(score));
    }

    let all_scores = [[70, 85, 92, 63], [59, 60, 60, 59], [0, 0, 0, 1]];
    for scores in all_scores {
        let (average, best) = average_and_best(scores);
        println!("average {average}, best {best}, grade {}", letter(average as u32));
    }

    println!("score 75, bonus 5: {} rounds", rounds_to_pass(75, 5));
    println!("score 50, bonus 4: {} rounds", rounds_to_pass(50, 4));
    println!("score 10, bonus 25: {} rounds", rounds_to_pass(10, 25));
}
